export const SLOT_NAMES=['Оружие','Доп. оружие / щит','Шлем','Нагрудник','Штаны','Обувь'];
export function createInventory(){return Array(20).fill(null)}
export function addItem(slots,id,count=1){const same=slots.findIndex((s,i)=>i>=6&&i<18&&s?.id===id);const index=same>=0?same:slots.findIndex((s,i)=>i>=6&&i<18&&!s);if(index<0)return false;if(slots[index])slots[index].count+=count;else slots[index]={id,count};return true}
export function countItem(slots,id){return slots.reduce((n,s)=>n+(s?.id===id?s.count:0),0)}
export function removeItem(slots,id,count=1){if(countItem(slots,id)<count)return false;for(let i=0;i<slots.length&&count;i++){if(slots[i]?.id!==id)continue;const take=Math.min(count,slots[i].count);slots[i].count-=take;count-=take;if(!slots[i].count)slots[i]=null}return true}
export function moveItem(slots,from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=slots.length||to>=slots.length||from===to||!slots[from])return false;const fits=(item,index)=>!item||(index>=6&&index<18)||(index>=18?ITEMS[item.id]?.slot==='ring':ITEMS[item.id]?.slot===index);if(!fits(slots[from],to)||!fits(slots[to],from))return false;if(slots[to]?.id===slots[from].id&&to>=6&&to<18){slots[to].count+=slots[from].count;slots[from]=null}else [slots[from],slots[to]]=[slots[to],slots[from]];return true}
export function itemIcon(id){if(ITEMS[id]?.weaponClass)return '<span class="fine-item">'+itemIcon(ITEMS[id].weaponClass)+'</span>';if(ITEMS[id]?.atlas)return '<span class="item-art" style="background-position:'+ITEMS[id].atlas+'"></span>'; if(ITEMS[id]?.slot===2)return '<svg viewBox="0 0 64 64" width="48" height="48"><path d="M12 55V28Q12 5 32 5Q52 5 52 28V55L42 49V30Q32 18 22 30V49Z" fill="'+ITEMS[id].color+'" stroke="#d4c5a2" stroke-width="2"/><path d="M16 21H48M16 26H48M16 32H22M42 32H48" stroke="#39353c" stroke-width="2"/></svg>';const shapes={shield:'<path d="M10 8H54V31Q51 49 32 60Q13 49 10 31Z" fill="#8c6543" stroke="#b4babe" stroke-width="4"/><path d="M32 10V55M13 28H51" stroke="#b4babe" stroke-width="3"/>',sword:'<path d="M27 4L34 4L33 40L26 40Z" fill="#c5d5dd"/><path d="M18 40H41M30 42V57" stroke="#bb9858" stroke-width="5"/>',bow:'<path d="M19 6Q57 32 19 58" fill="none" stroke="#b58c50" stroke-width="5"/><path d="M19 6V58M8 32H48L41 27M48 32L41 37" fill="none" stroke="#e1d5ae" stroke-width="2"/>',mage:'<path d="M30 22V58" stroke="#98724a" stroke-width="6"/><path d="M30 4L40 17L30 29L20 17Z" fill="#ff9952"/>',arrow:'<path d="M15 52L46 12M46 12L34 17M46 12L44 25M15 52L13 40M15 52L27 49" stroke="#dbd0a9" stroke-width="3" fill="none"/>',carcass:'<ellipse cx="31" cy="33" rx="17" ry="12" fill="#bc827b"/><ellipse cx="46" cy="24" rx="8" ry="7" fill="#c89c88"/><path d="M43 19L38 7M49 18L49 6M19 37L11 48M34 41L39 50" stroke="#c89c88" stroke-width="6"/>',fang:'<path d="M20 8Q48 6 42 29Q36 48 15 57Q30 34 20 8" fill="#e8dfbf"/><path d="M20 8Q32 18 44 16" stroke="#9e947d" fill="none"/>'};const extra={3:'M8 12L20 6L26 16H38L44 6L56 12L50 29L44 25V57H20V25L14 29Z',4:'M16 7H48L51 57H35L32 30L29 57H13Z',5:'M14 8H30V39L34 46V57H5V47L14 39ZM39 8H55V42L61 48V57H38Z'};const special=ITEMS[id]?.slot==='ring'?'<circle cx="32" cy="36" r="17" fill="none" stroke="#d9b56e" stroke-width="6"/><path d="M23 18L32 7L42 18L32 27Z" fill="'+ITEMS[id].color+'"/>':['health_potion','mana_potion','ritual_elixir','strength_potion'].includes(id)?'<path d="M25 6H39V22Q57 35 46 53Q32 64 18 53Q7 35 25 22Z" fill="'+ITEMS[id].color+'" stroke="#e6d7b4" stroke-width="3"/><path d="M24 8H40" stroke="#9b7646" stroke-width="8"/>':id==='ritual_page'?'<path d="M16 6H48L51 58H13Z" fill="#d7c698"/><path d="M22 22H42M22 31H39M22 40H43" stroke="#5c4b65" stroke-width="3"/>':id==='torch'?'<path d="M29 32H36V60H29Z" fill="#a27440"/><path d="M33 3Q51 24 40 35Q20 43 21 25Q29 30 33 3" fill="#ff9a36"/><path d="M33 18Q42 33 33 34Q27 31 33 18" fill="#ffe9a3"/>':id==='bone'?'<path d="M19 18L46 45" stroke="#e4dfc2" stroke-width="10"/><circle cx="15" cy="18" r="7" fill="#e4dfc2"/><circle cx="22" cy="13" r="7" fill="#e4dfc2"/><circle cx="43" cy="49" r="7" fill="#e4dfc2"/><circle cx="50" cy="42" r="7" fill="#e4dfc2"/>':id==='shield_fine'?shapes.shield:id==='quiver'?'<path d="M19 18L40 21L39 56H17Z" fill="#95613d"/><path d="M22 28L27 3M31 29L39 4M38 30L49 10" stroke="#d6d8b7" stroke-width="3"/>':['grimoire','witch_relic'].includes(id)?'<path d="M10 9L48 6L54 53L16 57Z" fill="'+ITEMS[id].color+'" stroke="#d4c5a2" stroke-width="3"/><path d="M25 22L40 33L29 44L24 30Z" fill="#e4ecc5"/>':extra[ITEMS[id]?.slot]?'<path d="'+extra[ITEMS[id].slot]+'" fill="'+ITEMS[id].color+'" stroke="#d4c5a2" stroke-width="2"/>':'';return '<svg viewBox="0 0 64 64" width="48" height="48" aria-hidden="true">'+(special||shapes[id]||'')+'</svg>'}
